CREATE TABLE IF NOT EXISTS app_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,password_hash text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS auth_sessions_user ON auth_sessions(user_id);
CREATE TABLE IF NOT EXISTS password_resets (token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_attempts (bucket text PRIMARY KEY,attempts integer NOT NULL DEFAULT 0,window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles (user_id uuid PRIMARY KEY REFERENCES app_users(id) ON DELETE CASCADE,email text,display_name text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,title text NOT NULL DEFAULT 'New conversation',provider text,model text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,user_id));
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),conversation_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('user','assistant','system','tool')),content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),attachment_metadata jsonb,execution_metadata jsonb,FOREIGN KEY(conversation_id,user_id) REFERENCES conversations(id,user_id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS messages_conversation_time ON messages(conversation_id,created_at);
CREATE INDEX IF NOT EXISTS conversations_user_updated ON conversations(user_id,updated_at DESC);
CREATE TABLE IF NOT EXISTS provider_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,provider text NOT NULL,active boolean NOT NULL DEFAULT true,default_model text,temperature real NOT NULL DEFAULT 0.7 CHECK(temperature BETWEEN 0 AND 2),max_tokens integer NOT NULL DEFAULT 1024 CHECK(max_tokens BETWEEN 1 AND 32768),connection_status text NOT NULL DEFAULT 'untested',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,provider));
CREATE TABLE IF NOT EXISTS provider_secrets (user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,provider text NOT NULL,ciphertext text NOT NULL,PRIMARY KEY(user_id,provider),FOREIGN KEY(user_id,provider) REFERENCES provider_configs(user_id,provider) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS preferences (user_id uuid PRIMARY KEY REFERENCES app_users(id) ON DELETE CASCADE,preferred_provider text,preferred_model text,preferred_voice text,speech_rate real NOT NULL DEFAULT 1,voice_enabled boolean NOT NULL DEFAULT false,personality text,interface_preferences jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS memories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,conversation_id uuid,provider text NOT NULL,model text NOT NULL,status text NOT NULL,input_tokens integer,output_tokens integer,created_at timestamptz NOT NULL DEFAULT now());
